#!/usr/bin/env python3
"""Flag log lines that need on-call engineer attention using typesafe.ai's Jev model."""

import argparse
import asyncio
import sys

from typesafe_sdk import AsyncTypeSafeClient, Noul, RetryPolicy, TypeSafeAPIError

BATCH_SIZE = 25       # log lines packed into a single request (one Noul question per line)
CONCURRENCY = 20      # requests in flight at once
THRESHOLD = 0.5       # noul probability above which a line is flagged

CRITERIA = {
    "true": "The line signals an active incident requiring immediate human intervention.",
    "false": "The line is routine, informational, or a transient/expected warning.",
}


def read_batches(path, batch_size):
    batch = []
    with open(path, "r", encoding="utf-8", errors="replace") as f:
        for line_no, raw_line in enumerate(f):
            line = raw_line.rstrip("\n")
            if not line.strip():
                continue
            batch.append((line_no, line))
            if len(batch) >= batch_size:
                yield batch
                batch = []
    if batch:
        yield batch


async def process_batch(client, semaphore, batch, threshold):
    keys = [f"l{line_no}" for line_no, _ in batch]
    state = {"lines": {key: text for key, (_, text) in zip(keys, batch)}}
    questions = {
        key: Noul(
            instructions=(
                f"Does the log line at `lines.{key}` describe a problem serious "
                "enough that an on-call engineer should be paged right now "
                "(e.g. an outage, crash, data loss, security incident, or a "
                "critical/repeating error), as opposed to routine or "
                "informational output?"
            ),
            criteria=CRITERIA,
        )
        for key in keys
    }
    async with semaphore:
        response = await client.system_one(state=state, questions=questions)
    return [
        (line_no, text)
        for key, (line_no, text) in zip(keys, batch)
        if response.nouls[key].noul > threshold
    ]


async def label_logs(log_path, output_path, batch_size, concurrency, threshold):
    semaphore = asyncio.Semaphore(concurrency)
    retry = RetryPolicy(max_retries=5)

    flagged_by_line = {}
    batches = list(read_batches(log_path, batch_size))
    total = len(batches)

    async with AsyncTypeSafeClient(retry=retry) as client:
        tasks = [
            asyncio.create_task(process_batch(client, semaphore, batch, threshold)) for batch in batches
        ]
        done = 0
        for task in asyncio.as_completed(tasks):
            done += 1
            try:
                for line_no, text in await task:
                    flagged_by_line[line_no] = text
            except TypeSafeAPIError as error:
                print(f"warning: skipping a batch after API error: {error}", file=sys.stderr)
            if done % 50 == 0 or done == total:
                print(f"processed {done}/{total} batches", file=sys.stderr)

    with open(output_path, "w", encoding="utf-8") as out:
        for line_no in sorted(flagged_by_line):
            out.write(flagged_by_line[line_no] + "\n")

    print(f"flagged {len(flagged_by_line)} line(s) -> {output_path}", file=sys.stderr)


def parse_args():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("log_file", help="Path to the log file, one entry per line.")
    parser.add_argument("-o", "--output", default="flagged.txt", help="Path to write flagged lines to.")
    parser.add_argument("--batch-size", type=int, default=BATCH_SIZE, help="Log lines per API request.")
    parser.add_argument("--concurrency", type=int, default=CONCURRENCY, help="Concurrent requests in flight.")
    parser.add_argument("--threshold", type=float, default=THRESHOLD, help="Noul probability cutoff to flag a line.")
    return parser.parse_args()


if __name__ == "__main__":
    args = parse_args()
    asyncio.run(label_logs(args.log_file, args.output, args.batch_size, args.concurrency, args.threshold))

#!/usr/bin/env python3
"""Flag log lines that need an on-call engineer, using TypeSafe's Jev model."""

import argparse
import asyncio
import sys

from typesafe_sdk import AsyncTypeSafeClient, Noul, RetryPolicy, TypeSafeAPIError

INSTRUCTIONS_TEMPLATE = (
    "Does the application log line at `lines[{i}]` describe a problem serious "
    "enough that an on-call engineer needs to be paged right now?"
)
CRITERIA = {
    "true": (
        "A crash, unhandled exception, service outage, data loss, security "
        "incident, resource exhaustion, or other critical failure needing "
        "immediate human intervention."
    ),
    "false": (
        "Routine informational or debug output, or an error that is already "
        "handled/recovered and does not need immediate attention."
    ),
}


def chunked(items, size):
    for start in range(0, len(items), size):
        yield items[start : start + size]


async def classify_batch(client, retry, batch, threshold):
    """Return the subset of (index, line) pairs in `batch` that should be flagged."""
    questions = {
        str(i): Noul(instructions=INSTRUCTIONS_TEMPLATE.format(i=i), criteria=CRITERIA)
        for i in range(len(batch))
    }
    state = {"lines": [line for _, line in batch]}

    try:
        response = await client.system_one(state=state, questions=questions, retry=retry)
    except TypeSafeAPIError as exc:
        first_idx = batch[0][0]
        last_idx = batch[-1][0]
        print(
            f"warning: batch for lines {first_idx}-{last_idx} failed ({exc}); "
            "flagging them for manual review",
            file=sys.stderr,
        )
        return list(batch)

    flagged = []
    for i, (idx, line) in enumerate(batch):
        if response.nouls[str(i)].noul >= threshold:
            flagged.append((idx, line))
    return flagged


async def run(args):
    with open(args.log_file, encoding="utf-8", errors="replace") as f:
        lines = [line.rstrip("\n") for line in f]

    non_blank = [(idx, line) for idx, line in enumerate(lines) if line.strip()]
    batches = list(chunked(non_blank, args.batch_size))

    retry = RetryPolicy(max_retries=5, backoff_max=10.0, timeout=60.0)
    semaphore = asyncio.Semaphore(args.concurrency)
    done = 0

    async def bounded_classify(batch):
        nonlocal done
        async with semaphore:
            result = await classify_batch(client, retry, batch, args.threshold)
        done += 1
        if done % 10 == 0 or done == len(batches):
            print(f"processed {done}/{len(batches)} batches", file=sys.stderr)
        return result

    async with AsyncTypeSafeClient(model=args.model) as client:
        results = await asyncio.gather(*(bounded_classify(batch) for batch in batches))

    flagged_indices = {idx for batch_result in results for idx, _ in batch_result}

    with open(args.output, "w", encoding="utf-8") as out:
        for idx, line in enumerate(lines):
            if idx in flagged_indices:
                out.write(line + "\n")

    print(f"flagged {len(flagged_indices)}/{len(lines)} lines -> {args.output}", file=sys.stderr)


def parse_args():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("log_file", help="path to the log file, one entry per line")
    parser.add_argument("-o", "--output", default="flagged.txt", help="output file for flagged lines")
    parser.add_argument("--batch-size", type=int, default=100, help="log lines classified per API call")
    parser.add_argument("--concurrency", type=int, default=20, help="max in-flight API calls")
    parser.add_argument("--threshold", type=float, default=0.5, help="min probability to flag a line")
    parser.add_argument("--model", default=None, help="override the TypeSafe model (defaults to Jev)")
    return parser.parse_args()


if __name__ == "__main__":
    asyncio.run(run(parse_args()))

"""Grade a support agent's reply using typesafe.ai's Jev model.

Requires `TYPESAFE_API_KEY` to be set in the environment.
"""

from typesafe_sdk import Noul, TypeSafeClient

MODEL = "jev-latest"

# Below this probability a Noul judgment is treated as "no" for the rubric.
DECISION_THRESHOLD = 0.5

# A refund promise is a hard policy violation, not something other strengths
# can offset, so it caps the score instead of being averaged in.
REFUND_VIOLATION_SCORE_CAP = 3.0


def grade(customer_message: str, agent_reply: str) -> dict:
    state = {
        "customer_message": customer_message,
        "agent_reply": agent_reply,
    }

    questions = {
        "consistent": Noul(
            instructions=(
                "Does `agent_reply` accurately reflect what the customer said in "
                "`customer_message`, without contradicting, misquoting, or "
                "mischaracterizing it?"
            ),
            criteria={
                "true": "The reply's claims about the situation match what the customer described.",
                "false": "The reply contradicts, ignores, or misstates something the customer said.",
            },
        ),
        "polite": Noul(
            instructions="Is `agent_reply` polite and respectful in tone toward the customer?",
            criteria={
                "true": "The tone is courteous and respectful throughout.",
                "false": "The tone is rude, dismissive, curt, or condescending anywhere in the reply.",
            },
        ),
        "resolves_issue": Noul(
            instructions=(
